pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address nonOwner) public {
        // Keep domain wide: ensure nonOwner != Owner
        vm.assume(nonOwner != c.Owner());
        vm.assume(amount > 0);

        // Give the contract some Ether
        vm.deal(address(c), amount);

        // Record Owner's balance before the non-owner attempts withdrawal
        address owner = c.Owner();
        uint256 ownerBalBefore = owner.balance;

        // Non-owner attempts to withdraw
        vm.prank(nonOwner);
        bool ok;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // In the correct contract, non-owner call must revert and Owner's balance unchanged;
        // in the buggy version, it succeeds and Owner receives the contract's balance.
        // Universal rule: after a non-owner call, either (correct) it reverts and Owner balance unchanged,
        // or (bug) it succeeds and Owner balance = ownerBalBefore + amount.
        // The correct contract always satisfies the first disjunct; the buggy one can violate it.
        uint256 ownerBalAfter = owner.balance;
        assertTrue(!ok || ownerBalAfter == ownerBalBefore + amount);
    }
}

