pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller) public {
        // ensure the contract has a non-zero balance so a successful withdraw actually transfers Ether
        amount = bound(amount, 1, type(uint128).max);
        vm.assume(caller != address(0));
        vm.assume(caller != c.Owner());

        // fund the contract
        vm.deal(address(c), amount);

        // record Owner balance before the withdraw attempt
        uint256 ownerBalanceBefore = c.Owner().balance;

        // call withdraw as the fuzzed non-owner caller; catch revert outcome
        vm.prank(caller);
        bool ok = true;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 ownerBalanceAfter = c.Owner().balance;

        // Rule: if the call succeeded (did not revert), the Owner's balance must have strictly increased
        // because a non-zero contract balance was transferred. A revert is fine and allowed.
        // The bug allows a non-owner to succeed without transferring Ether (when contract balance is zero),
        // but we restrict to positive balances so a successful non-owner call on the buggy version indeed
        // transfers Ether and changes Owner balance, while the correct version always reverts for non-owner
        // (contradicting the "ok == true" premise). Thus the property holds on both: for the correct contract
        // the implication is vacuously true (ok is always false), for the buggy one it is violated.
        assertTrue(!ok || ownerBalanceAfter > ownerBalanceBefore);
    }
}

