pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = c.Owner();
    }

    function testFuzz_property(uint256 amount, address sender) public {
        // Restrict sender to be a valid address distinct from owner to expose the bug path
        vm.assume(sender != owner);
        vm.assume(sender != address(0));
        vm.assume(sender != address(this));
        vm.assume(sender != address(c));
        // Restrict amount to keep contract balance manageable
        bound(amount, 0, address(this).balance / 2);

        // Fund the contract
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = owner.balance;
        uint256 senderBalanceBefore = sender.balance;

        // Sender (not owner) attempts withdrawal
        vm.prank(sender);
        bool ok;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // Owner withdraws successfully
        vm.prank(owner);
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 ownerBalanceAfter = owner.balance;

        // Rule: if contract balance before owner's withdrawal was nonzero,
        // owner's balance must increase by exactly that amount, and contract balance becomes zero.
        // Non-owner attempts do not affect balances (they revert).
        // The bug sends to sender instead of owner, so owner's balance won't increase.
        if (balanceBefore > 0) {
            assertTrue(balanceAfter == 0 && ownerBalanceAfter == ownerBalanceBefore + balanceBefore);
        } else {
            assertTrue(balanceAfter == 0);
        }
    }
}

