import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 withdrawValue) public {
        // 1. Bound inputs to avoid overflow and keep domain wide but safe.
        initialBalance = bound(initialBalance, 1, address(c).balance);
        withdrawValue = bound(withdrawValue, 0, type(uint256).max - address(c).balance - 1);

        // 2. Fund the contract with Ether and ensure it’s at least 1 wei to trigger the bug.
        vm.deal(address(c), initialBalance);
        require(initialBalance >= 1, "balance must be at least 1");

