pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 preFund, address adr) public {
        // Restrict to admissible domain: Owner is not address(0) or the contract itself
        vm.assume(adr != address(c) && adr != address(0));
        // Ensure preFund and amount are not so large that funding fails
        bound(preFund, 1, address(this).balance);
        bound(amount, 0, preFund);

        // Fund the contract to a known pre-balance
        vm.deal(address(this), preFund);
        c.receive{value: preFund}();
        uint256 preBal = address(c).balance;

        // Adversarial callee that reverts would mask the bug (no balance change at all), so we need a callee that
        // accepts but does not revert. However, the fuzzed address is an EOA without code, and a low-level call to
        // an EOA always succeeds. That EOA will receive the forwarded value, and the contract balance will drop
        // correspondingly. This is sufficient to expose the difference: if the contract forwards the entire balance
        // (bug), the drop equals preBal; if it forwards `amount` (correct), the drop equals amount.
        // No adversarial helper is required here because the difference is purely in how much value is transferred
        // during the call, and an EOA callee reliably accepts Ether without reverting.
        vm.prank(c.Owner());
        try c.Command{value: amount}(adr, hex"00") {
            // call succeeded – assert the rule
            uint256 postBal = address(c).balance;
            // After a successful Command call, post-balance must equal pre-balance minus amount sent
            assertTrue(postBal == preBal - amount);
        } catch {
            // If the call itself reverted (unlikely with an EOA and no out-of-gas), nothing to assert
        }
    }
}

