pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address adr) public {
        // Bound amount to a range where overflow of balance + amount is possible.
        // To trigger the difference, we need msg.value >= address(c).balance and
        // address(c).balance + msg.value to overflow. We can send ether to c first
        // to set a non-zero balance and then call multiplicate with a large amount.
        vm.assume(adr != address(0) && adr != address(c) && adr != address(this));
        vm.assume(amount > 0);

        // First, make c have some balance. We'll send it a fixed amount that allows overflow
        // when amount is large enough. Send 1 ether to c.
        vm.deal(address(this), 1 ether);
        (bool sent,) = address(c).call{value: 1 ether}("");
        require(sent, "send ether to c failed");
        uint256 balBefore = address(c).balance;

        // Now call multiplicate from pranked address with amount as msg.value.
        vm.deal(adr, amount);
        vm.prank(adr);
        bool ok;
        try c.multiplicate{value: amount}(adr) { ok = true; } catch { ok = false; }

        uint256 balAfter = address(c).balance;

        // General rule: If amount >= balBefore, the call must revert if balBefore + amount overflows.
        // Otherwise (no overflow), it must either revert or leave balance zero (the transfer may succeed or
        // revert for other reasons, but the overflow condition is the key difference).
        // Since the bug removes the overflow check, the mutant may not revert when overflow happens,
        // and the transfer will send a non-overflowed amount (balBefore + amount) truncated to 256 bits,
        // leaving the contract with a non-zero balance. The reference always reverts on overflow.
        bool expectRevert = amount >= balBefore && (balBefore + amount) < balBefore; // overflow check
        // If overflow is expected, reference reverts; mutant might not.
        // If no overflow, no assertion about revert (both could succeed or fail for other reasons).
        if (expectRevert) {
            // Assert: The call must revert (reference behavior). Any non-revert is a bug.
            assertTrue(!ok, "should revert on overflow");
            // Also, balance must remain unchanged if reverted.
            assertTrue(balAfter == balBefore, "balance changed after revert");
        } else {
            // For completeness, we can assert nothing or just that if it succeeded, balance became zero
            // (which is not affected by the bug).
            // But the bug only manifests on overflow, which is not this branch.
            // So we allow any outcome here.
        }
    }
}

